// Konversi nilai angka -> huruf & keterangan, dipakai di tabel nilai rapor formal.
const nilaiHurufKeterangan = (angka) => {
  const n = Number(angka);
  if (isNaN(n)) return { huruf: "-", ket: typeof angka === "string" ? angka : "-" };
  if (n >= 90) return { huruf: "A", ket: "Sangat Baik" };
  if (n >= 85) return { huruf: "A-", ket: "Sangat Baik" };
  if (n >= 80) return { huruf: "B+", ket: "Baik" };
  if (n >= 75) return { huruf: "B", ket: "Baik" };
  if (n >= 70) return { huruf: "B-", ket: "Cukup" };
  if (n >= 65) return { huruf: "C+", ket: "Cukup" };
  if (n >= 60) return { huruf: "C", ket: "Cukup" };
  return { huruf: "D", ket: "Perlu Bimbingan" };
};
