// ---- Klien API Backend Bersama (Cashless BMT & Pengasuhan) ----
// URL bisa dioverride tanpa build ulang: taruh <script>window.BACKEND_API_BASE = "https://domain-anda/api";</script>
// SEBELUM tag <script> bundle ini di file HTML produksi. Default di bawah untuk pengembangan lokal.
const BACKEND_API_BASE = (typeof window !== "undefined" && window.BACKEND_API_BASE) || (typeof window !== "undefined" ? window.location.origin + "/api" : "http://localhost:4000/api");
async function backendApi(path, { method = "GET", token, body } = {}) {
  let res;
  try {
    res = await fetch(`${BACKEND_API_BASE}${path}`, {
      method,
      headers: { "Content-Type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch {
    throw new Error("Tidak bisa terhubung ke server. Periksa koneksi atau status server backend.");
  }
  let data = null;
  try { data = await res.json(); } catch { /* respons kosong */ }
  if (!res.ok) throw new Error(data?.error || `Server menolak permintaan (${res.status}).`);
  return data;
}
