const THEME_PROP_FOR = { bg: "background-color", text: "color", border: "border-color", from: "--tw-gradient-from", to: "--tw-gradient-to", via: "--tw-gradient-via-stops" };
const themeEscSel = (s) => s.replace(/[#\[\]\/]/g, (m) => "\\" + m);
const PRINT_GUARD = ":not(#print-area,#print-area *)";
const buildThemeOverrideCSS = (v) => {
  const rules = THEME_COLOR_MAP.map(([hex, cssVar, prefixes]) =>
    prefixes.map((p) => `.${themeEscSel(`${p}-[${hex}]`)}${PRINT_GUARD}{${THEME_PROP_FOR[p]}:${cssVar} !important;}`).join("")
  ).join("\n");
  const divideRule = `.${themeEscSel("divide-[#DCEDF7]")}${PRINT_GUARD} > :not([hidden]) ~ :not([hidden]){border-color:var(--c-border-soft) !important;}`;
  const ringOpacities = ["30", "40", "60", "85", "92", "95"];
  const ringRules = ringOpacities.map((op) => `.${themeEscSel(`ring-[#0C4A6E]/${op}`)}${PRINT_GUARD}{--tw-ring-color:rgb(var(--c-primary-rgb) / 0.${op}) !important;}`).join("");
  const fontRule = `[style*="Fraunces"]${PRINT_GUARD}{font-family:'${v.fontJudul}', serif !important;}`;
  const root = `:root{
    --c-primary:${v.warnaSekunder}; --c-primary-rgb:${hexToRgbTriplet(v.warnaSekunder)};
    --c-brand:${v.warnaPrimer}; --c-accent:${v.warnaPrimer}; --c-accent-bg:${v.warnaAksenBg};
    --c-grad:linear-gradient(135deg, ${v.warnaPrimer}, #4F7CFF 60%, #635BFF);
    --c-text:${v.warnaTeks}; --c-muted:${v.warnaTeksMuted};
    --c-muted-dark: color-mix(in srgb, ${v.warnaTeksMuted} 75%, black);
    --c-border:${v.warnaBorder}; --c-border-soft: color-mix(in srgb, ${v.warnaBorder} 55%, white);
    --c-surface:#FFFFFF;
    --c-surface-tint: color-mix(in srgb, ${v.warnaPrimer} 9%, white);
    --c-page-bg:${v.warnaLatarHalaman};
    --c-status-success:#12B76A; --c-status-success-bg:rgba(18, 183, 106, 0.1);
    --c-status-warning:#F79009; --c-status-warning-bg:rgba(247, 144, 9, 0.1);
    --c-status-danger:#D92D20; --c-status-danger-bg:rgba(217, 45, 32, 0.1);
    --c-status-info:${v.warnaPrimer}; --c-status-info-bg:color-mix(in srgb, ${v.warnaPrimer} 10%, transparent);
    --c-danger:#D92D20; --c-danger-dark:#96271A; --c-danger-tint: color-mix(in srgb, #D92D20 16%, white);
    --c-success:#12B76A; --c-success-tint: color-mix(in srgb, #12B76A 16%, white);
    --c-warning:#F79009; --c-warning-tint: color-mix(in srgb, #F79009 20%, white);
    --c-neutral-border: color-mix(in srgb, ${v.warnaTeksMuted} 22%, white);
    --c-muted-soft: color-mix(in srgb, ${v.warnaTeksMuted} 55%, white);
    --radius-sm:10px; --radius-md:16px; --radius-lg:24px;
    --shadow-sm:0 1px 2px rgba(10,37,64,.06);
    --shadow-md:0 8px 24px -8px rgba(10,37,64,.12);
    --shadow-lg:0 24px 48px -16px rgba(10,37,64,.18);
    --font-heading: '${v.fontJudul}', serif; --font-body: '${v.fontIsi}', sans-serif;
  }`;
  return `${root}\n${rules}\n${divideRule}\n${ringRules}\n${fontRule}`;
};
