// Konversi Masehi -> Hijriyah (algoritma tabular Kuwaiti — pendekatan aritmetik standar, ±1 hari dari hasil rukyat aktual).
const masehiKeHijri = (tanggal) => {
  const day = tanggal.getDate(), month = tanggal.getMonth() + 1, year = tanggal.getFullYear();
  const jd = Math.floor((1461 * (year + 4800 + Math.floor((month - 14) / 12))) / 4) +
    Math.floor((367 * (month - 2 - 12 * Math.floor((month - 14) / 12))) / 12) -
    Math.floor((3 * Math.floor((year + 4900 + Math.floor((month - 14) / 12)) / 100)) / 4) +
    day - 32075;
  let l = jd - 1948440 + 10632;
  const n = Math.floor((l - 1) / 10631);
  l = l - 10631 * n + 354;
  const j = Math.floor((10985 - l) / 5316) * Math.floor((50 * l) / 17719) + Math.floor(l / 5670) * Math.floor((43 * l) / 15238);
  l = l - Math.floor((30 - j) / 15) * Math.floor((17719 * j) / 50) - Math.floor(j / 16) * Math.floor((15238 * j) / 43) + 29;
  const hBulan = Math.floor((24 * l) / 709);
  const hHari = l - Math.floor((709 * hBulan) / 24);
  const hTahun = 30 * n + j - 30;
  return { tahun: hTahun, bulan: hBulan, hari: hHari };
};
const NAMA_BULAN_HIJRI = ["Muharram", "Shafar", "Rabi'ul Awwal", "Rabi'ul Akhir", "Jumadal Ula", "Jumadal Akhirah", "Rajab", "Sya'ban", "Ramadhan", "Syawwal", "Dzulqa'dah", "Dzulhijjah"];
const tanggalHijriLengkap = (tanggal) => { const h = masehiKeHijri(tanggal); return `${h.hari} ${NAMA_BULAN_HIJRI[h.bulan - 1]} ${h.tahun} H`; };

