const bulanSekarangLabel = () => {
  const NAMA = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const now = new Date();
  return `${NAMA[now.getMonth()]} ${now.getFullYear()}`;
};
// Hanya transaksi kategori "Jajan Harian" yang dihitung terhadap limit harian.
// Transaksi lama tanpa field kategori (sebelum fitur ini ada) dianggap Jajan Harian, agar rekap lama tidak berubah drastis.
const terpakaiHariIni = (santriId, transaksiCashless) => (transaksiCashless || [])
  .filter((t) => t.santriId === santriId && t.tanggal === todayStr() && t.jenis !== "Top Up" && (t.kategori || "Jajan Harian") === "Jajan Harian")
  .reduce((a, t) => a + t.jumlah, 0);
const sisaLimitHarian = (santri, transaksiCashless) => {
  const limit = santri?.limitJajanHarian || 0;
  if (!limit) return null; // 0/kosong = tidak dibatasi
  return Math.max(0, limit - terpakaiHariIni(santri.id, transaksiCashless));
};
