// Kotak pencarian santri dengan autocomplete (ketik nama untuk memfilter, klik untuk memilih).
// Dipakai bersama oleh Riwayat Akademik (Pengajaran) dan Ubudiyah & Doa (LPTQ) agar perilakunya identik.
function SantriSearchSelect({ santriList, value, onChange, placeholder }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const selected = santriList.find((s) => s.id === value);
  const q = query.trim().toLowerCase();
  const filtered = q ? santriList.filter((s) => s.nama.toLowerCase().includes(q) || (s.nis || "").toLowerCase().includes(q) || (s.nisn || "").toLowerCase().includes(q)) : santriList;
  return (
    <div className="relative flex-1 min-w-[160px]">
      <div className="relative">
        <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8FB0C7] pointer-events-none" />
        <input
          value={open ? query : (selected ? `${selected.nama}${selected.kelas ? " — " + selected.kelas : ""}` : "")}
          onChange={(e) => { setQuery(e.target.value); setOpen(true); if (!e.target.value) onChange(""); }}
          onFocus={() => { setQuery(""); setOpen(true); }}
          onBlur={() => setTimeout(() => setOpen(false), 140)}
          placeholder={placeholder || "Cari nama santri..."}
          className="w-full h-10 border border-[#E3E8EE] bg-white rounded-xl pl-9 pr-3 text-sm text-[#0A2540] placeholder:text-[#8FA3B3] focus:outline-none focus:ring-2 focus:ring-[#29AAE1]/30 focus:border-[#29AAE1] transition-colors shadow-sm"
        />
      </div>
      {open && (
        <div className="absolute z-20 mt-1.5 w-full max-h-56 overflow-y-auto bg-white border border-[#E3E8EE] rounded-xl shadow-lg animate-fadeIn divide-y divide-[#F2F4F7]">
          {filtered.length ? filtered.map((s) => (
            <div
              key={s.id}
              onMouseDown={() => { onChange(s.id); setQuery(""); setOpen(false); }}
              className="px-3.5 py-2.5 text-sm hover:bg-[#F4F8FB] cursor-pointer flex items-center justify-between gap-2 transition-colors"
            >
              <span className="font-medium text-[#0A2540] truncate">{s.nama}</span>
              <span className="text-[#5B7C93] text-xs shrink-0">{s.nis || s.nisn ? `${s.nis || "-"} / ${s.nisn || "-"} — ` : ""}{s.kelas}</span>
            </div>
          )) : <div className="px-3.5 py-3 text-sm text-[#5B7C93] text-center">Tidak ditemukan.</div>}
        </div>
      )}
    </div>
  );
}

