// Navigasi menu minimalis: Sidebar vertikal di layar besar, pill horizontal ringkas di mobile.
// Menggantikan <Tabs/> secara struktural — dipakai berdampingan dengan area konten (flex row).
function Sidebar({ tabs, active, onChange }) {
  const itemRefs = useRef([]);
  itemRefs.current = [];
  const registerRef = (el) => el && itemRefs.current.push(el);

  const handleKeyDown = (e) => {
    const items = itemRefs.current;
    const i = items.indexOf(document.activeElement);
    if (e.key === "ArrowDown") { e.preventDefault(); items[(i + 1) % items.length]?.focus(); }
    else if (e.key === "ArrowUp") { e.preventDefault(); items[(i - 1 + items.length) % items.length]?.focus(); }
  };

  return (
    <>
      {/* Sidebar sungguhan — fixed penuh dari bawah TopBar (top-16) sampai
          ke dasar layar (bottom-0), independen dari scroll konten dashboard.
          Ruang untuk sidebar ini disediakan oleh padding-left di GuruDashboard
          (lg:pl-64), bukan oleh spacer lokal, supaya Header dan KPI di atas
          panel ini juga ikut bergeser dan tidak tertutup sidebar. */}
      <div className="hidden lg:flex flex-col w-64 fixed top-16 left-0 bottom-0 z-30 bg-white border-r border-[#E3E8EE] shadow-sm overflow-hidden">
        <div className="px-4 pt-3.5 pb-2">
          <p className="text-[10px] font-bold tracking-[0.14em] uppercase text-[#8FA3B3]">Menu Navigasi</p>
        </div>
        <nav aria-label="Navigasi bagian" onKeyDown={handleKeyDown} className="flex-1 overflow-y-auto flex flex-col gap-1 px-3 py-1">
          {tabs.map((t) => {
            const isActive = active === t.key;
            return (
              <button
                key={t.key}
                ref={registerRef}
                role="menuitem"
                aria-current={isActive ? "page" : undefined}
                onClick={() => onChange(t.key)}
                className={`group relative flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-sm text-left transition-all duration-150 outline-none focus-visible:ring-2 focus-visible:ring-[#29AAE1] shrink-0 ${
                  isActive
                    ? "bg-[#F0F9FF] text-[#0C4A6E] font-semibold border-l-4 border-[#29AAE1] shadow-xs"
                    : "text-[#5B7C93] hover:bg-[#F4F8FB] hover:text-[#0A2540]"
                }`}
              >
                <t.icon
                  size={17}
                  strokeWidth={isActive ? 2 : 1.75}
                  className={`shrink-0 transition-transform duration-150 group-hover:scale-105 ${
                    isActive ? "text-[#29AAE1]" : "text-[#8FA3B3] group-hover:text-[#0C4A6E]"
                  }`}
                />
                <span className="truncate">{t.label}</span>
              </button>
            );
          })}
        </nav>
        <div className="relative shrink-0 p-4 m-3 rounded-2xl bg-gradient-to-br from-[#0C4A6E] to-[#083550] text-center overflow-hidden shadow-sm">
          <img src={BUILDING_PHOTO} alt="" className="absolute inset-0 w-full h-full object-cover opacity-15 mix-blend-luminosity" />
          <div className="relative z-10">
            <p className="text-[12px] font-semibold text-white/95 tracking-wide leading-tight" style={{ fontFamily: "'Fraunces', serif" }}>
              Berilmu · Berakhlak · Berdaya
            </p>
            <p className="text-[10px] text-white/70 mt-1">Ma'had Mudaiyatul Anwar</p>
          </div>
        </div>
      </div>
      <div role="menu" aria-label="Navigasi bagian" className="flex lg:hidden gap-1.5 overflow-x-auto pb-1 mb-2 w-full -mx-1 px-1">
        {tabs.map((t) => {
          const isActive = active === t.key;
          return (
            <button
              key={t.key}
              role="menuitem"
              aria-current={isActive ? "page" : undefined}
              onClick={() => onChange(t.key)}
              className={`flex items-center gap-1.5 px-3.5 py-2 text-sm rounded-xl whitespace-nowrap transition-all duration-150 font-medium ${
                isActive
                  ? "bg-gradient-to-r from-[#29AAE1] to-[#0C4A6E] text-white shadow-sm"
                  : "bg-white border border-[#E3E8EE] text-[#5B7C93] hover:bg-[#F4F8FB]"
              }`}
            >
              <t.icon size={15} strokeWidth={1.75} />
              {t.label}
            </button>
          );
        })}
      </div>
    </>
  );
}

// ---------- PRINT OVERLAY (kwitansi & laporan siap cetak) ----------

function PrintOverlay({ content, onClose }) {
  const [mengunduh, setMengunduh] = useState(false);
  const [errorUnduh, setErrorUnduh] = useState("");
  if (!content) return null;

  const unduhPdf = async () => {
    setErrorUnduh("");
    setMengunduh(true);
    try {
      const area = document.getElementById("print-area");
      const halaman = Array.from(area.querySelectorAll(".pdf-page"));
      const target = halaman.length ? halaman : [area.firstElementChild || area];
      const pdf = new jsPDF({ unit: "mm", format: "a4" });
      const lebarHalaman = 210, tinggiHalaman = 297;
      for (let i = 0; i < target.length; i++) {
        const canvas = await html2canvas(target[i], { scale: 2, useCORS: true, backgroundColor: "#ffffff" });
        const dataUrl = canvas.toDataURL("image/png");
        let w = lebarHalaman;
        let h = (canvas.height * w) / canvas.width;
        if (h > tinggiHalaman) { h = tinggiHalaman; w = (canvas.width * h) / canvas.height; }
        const x = (lebarHalaman - w) / 2;
        if (i > 0) pdf.addPage();
        pdf.addImage(dataUrl, "PNG", x, 0, w, h);
      }
      pdf.save(`dokumen-${Date.now()}.pdf`);
    } catch (err) {
      setErrorUnduh("Gagal membuat PDF. Coba lagi, atau gunakan tombol Cetak lalu pilih 'Simpan sebagai PDF'.");
    } finally {
      setMengunduh(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4 print:bg-white print:p-0 print:block" id="print-wrapper">
      <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto print:max-h-none print:shadow-none print:max-w-none" id="print-area">
        <div className="p-6" style={{ fontFamily: "'Inter', sans-serif" }}>{content}</div>
      </div>
      <div className="fixed bottom-6 flex flex-col items-center gap-2 print:hidden">
        {errorUnduh && <p className="text-xs bg-white text-[#96271A] px-3 py-1.5 rounded-lg shadow">{errorUnduh}</p>}
        <div className="flex gap-2">
          <button onClick={() => window.print()} className="flex items-center gap-1.5 bg-[#0C4A6E] text-white text-sm px-5 py-2.5 rounded-xl hover:bg-[#0B3A57] hover:shadow-lg active:scale-95"><Printer size={16} />Cetak</button>
          <button onClick={unduhPdf} disabled={mengunduh} className="flex items-center gap-1.5 bg-white border border-[#0C4A6E] text-[#0C4A6E] text-sm px-5 py-2.5 rounded-xl hover:bg-[#EAF4FB] active:scale-95 disabled:opacity-60">
            {mengunduh ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
            {mengunduh ? "Membuat PDF..." : "Download PDF"}
          </button>
          <button onClick={onClose} className="bg-white border border-[#CFE3F0] text-[#45657A] text-sm px-5 py-2.5 rounded-xl">Tutup</button>
        </div>
      </div>
    </div>
  );
}

