          {backendOnline === false && <p className="flex items-center gap-1.5 text-xs text-[#96271A] bg-[#FBE4E1] border border-[#F3C9C2] rounded-xl px-3 py-1.5"><ShieldAlert size={13} className="shrink-0" />Tidak terhubung ke server. Infaq tidak bisa dicatat — coba logout lalu login ulang.</p>}
          {cashflowFetch.error && <p className="text-xs text-[#B5533C]">{cashflowFetch.error}</p>}
