            <div className="bg-white/70 backdrop-blur-xl border border-white/60 shadow-[0_10px_30px_-10px_rgba(12,74,110,0.12)] bg-white/70 backdrop-blur-sm rounded-xl focus:outline-none focus:ring-2 focus:ring-[#0C4A6E]/30 focus:border-[#0C4A6E] transition-colors p-4 text-center"><p className="text-lg font-semibold text-[#0C4A6E]" style={{ fontFamily: "'Fraunces', serif" }}>{rupiah(infaqBulanTerpilih.reduce((a, c) => a + c.jumlah, 0))}</p><p className="text-[11px] text-[#5B7C93] mt-0.5">Infaq {infaqBulanFilter}</p></div>
