          {backendOnline === false && <p className="flex items-center gap-1.5 text-xs text-[#96271A] bg-[#FBE4E1] border border-[#F3C9C2] rounded-xl px-3 py-1.5"><ShieldAlert size={13} className="shrink-0" />Tidak terhubung ke server. Pengajuan anggaran tidak bisa diproses — coba logout lalu login ulang.</p>}
          {anggaranFetch.error && <p className="text-xs text-[#B5533C]">{anggaranFetch.error}</p>}
