              <button key={o.k} onClick={() => { setPeriodeTipe(o.k); setPeriodeIdx(0); }} className={`text-xs px-3 py-1.5 rounded-full border transition-all duration-200 ${periodeTipe === o.k ? "btn-gradient border-[#0C4A6E]" : "border-[#CFE3F0] text-[#45657A]"}`}>{o.l}</button>
