                <button onClick={() => setCfForm({ ...cfForm, jenis: "Keluar" })} className={`flex items-center gap-1 text-xs px-3 py-2 rounded-xl border ${cfForm.jenis === "Keluar" ? "bg-[#B5533C] text-white border-[#B5533C]" : "border-[#CFE3F0] text-[#45657A]"}`}><TrendingDown size={13} />Keluar</button>
