                    <div className="min-w-0"><p className="text-[#17242E] truncate">{c.kategori} <span className="text-[#5B7C93]">— {c.keterangan || "-"}</span></p><p className="text-[10px] text-[#5B7C93]">{c.tanggal}</p></div>
