            <input placeholder="Keterangan (opsional)" value={kegiatanForm.keterangan} onChange={(e) => setKegiatanForm({ ...kegiatanForm, keterangan: e.target.value })} className="flex-1 min-w-[140px] border border-[#CFE3F0] bg-white/70 backdrop-blur-sm rounded-xl focus:outline-none focus:ring-2 focus:ring-[#0C4A6E]/30 focus:border-[#0C4A6E] transition-colors px-3 py-2 text-sm" />
