            <input placeholder="Pengirim / instansi asal" value={suratMasukForm.pengirim} onChange={(e) => setSuratMasukForm({ ...suratMasukForm, pengirim: e.target.value })} className="border border-[#CFE3F0] bg-white/70 backdrop-blur-sm rounded-xl focus:outline-none focus:ring-2 focus:ring-[#0C4A6E]/30 focus:border-[#0C4A6E] transition-colors px-3 py-2 text-sm" />
